<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue';import {useWorkbench} from '../stores/workbench';import {api,post,fmt} from '../api/client';import StatusBadge from './StatusBadge.vue';import UiIcon from './UiIcon.vue';const s=useWorkbench(),mode=ref('mock'),ack=ref(false),liveLogs=ref<string[]>([]);let timer:ReturnType<typeof setTimeout>|undefined,events:EventSource|undefined;const names:Record<string,string>={pending:'等待执行',running:'运行中',completed:'已完成',done:'已完成',failed:'执行失败',error:'执行失败',mock:'黑盒占位',optimal:'外部报告最优',feasible:'外部报告可行',infeasible:'外部报告不可行'};function close(){if(timer)clearTimeout(timer);events?.close()}async function poll(id:string){try{s.job=await api('/jobs/'+id);if(['pending','running','queued'].includes(s.job.status)){timer=setTimeout(()=>poll(id),800)}else{close();s.busy=false;await s.loadResults();await s.loadLogs();}}catch(e:any){close();s.busy=false;s.error=e.message}}async function run(){s.busy=true;s.error='';liveLogs.value=[];try{s.job=await post('/tasks/'+s.taskId+'/solve',{mode:mode.value,acknowledge_warnings:ack.value});events=new EventSource('/api/jobs/'+s.job.job_id+'/log');events.onmessage=e=>{try{const x=JSON.parse(e.data);liveLogs.value.push(x.message||x.log||String(e.data))}catch{liveLogs.value.push(e.data)}};events.addEventListener('log',(e:any)=>{liveLogs.value.push(e.data)});events.onerror=()=>events?.close();await poll(s.job.job_id)}catch(e:any){s.error=e.message;s.busy=false;close();}}async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{await s.guard(async()=>{const data=JSON.parse(await f.text());await post('/tasks/'+s.taskId+'/results/import',{result:data,acknowledge_warnings:ack.value});await s.loadResults();await s.loadLogs();})}catch{}}
onBeforeUnmount(close);
</script><template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">M5 / 外部计算适配</div><h2>求解黑盒 <StatusBadge name="求解"/></h2></div><span class="subtle-pill">版本 v{{s.spec.version}}</span></div><div class="notice"><UiIcon name="info"/><span>求解器黑盒 · 选择演示占位、导入结果或外部服务</span></div><div class="mode-grid"><button v-for="m in [{id:'mock',title:'黑盒占位',desc:'展示调整前真实断面'},{id:'import',title:'导入结果',desc:'校验并读取结果 JSON'},{id:'external',title:'外部命令',desc:'接入已配置的求解链'}]" :key="m.id" :class="{selected:mode===m.id}" @click="mode=m.id"><span>{{m.id.toUpperCase()}}</span><strong>{{m.title}}</strong><small>{{m.desc}}</small></button></div><div class="detail-grid solver-params"><div><span>指定求解器</span><strong>{{s.spec.solver_req.solver}}</strong></div><div><span>时间上限</span><strong>{{s.spec.solver_req.time_limit_s}} s</strong></div><div><span>收敛容差</span><strong>{{s.spec.solver_req.tolerance}}</strong></div><div><span>基础 N−1</span><strong>{{s.spec.omega.n_minus_1?'开启':'关闭'}}</strong></div></div><div class="notice amber" v-if="s.check?.warnings"><el-checkbox v-model="ack" data-testid="ack-warnings">我已阅读并确认本版本的 {{s.check.warnings}} 项校验警告</el-checkbox></div><div v-if="mode==='import'" class="upload-zone"><UiIcon name="file" :size="32"/><h3>导入本版本的求解结果</h3><p>支持标准结果 JSON，时段长度、编号与数值类型由后端验证。</p><label class="upload-button"><input type="file" accept=".json" @change="upload" data-testid="result-file" :disabled="!s.confirmed||!s.check||!!s.check.errors||(!!s.check.warnings&&!ack)"/>选择结果 JSON</label><p class="small-note">导入前须确认规格、完成当前版本校验，并确认所有警告。</p></div><template v-else><div v-if="mode==='external'" class="notice amber">通过 SOLVER_CMD 接入求解服务；未配置时不可运行。</div><div class="panel-bottom-actions"><span class="muted">{{s.check?.errors?'当前版本存在校验错误，不能执行。':!s.check?'请先完成五层校验。':!s.confirmed?'请先确认并保存规格。':'校验完成后可通过黑盒适配器继续。'}}</span><el-button type="primary" :loading="s.busy" :disabled="!s.confirmed||!s.check||!!s.check.errors||(!!s.check.warnings&&!ack)" @click="run" data-testid="run-solver">{{mode==='mock'?'运行黑盒占位':'启动外部命令'}}</el-button></div></template><section v-if="s.job||s.results?.result" class="solver-result"><div class="section-heading"><h3>任务状态</h3><span class="mode-badge">{{names[s.results?.result?.status||s.job?.status]||s.job?.status}}</span></div><div v-if="s.results?.result?.status==='mock'" class="notice amber">基态展示 · 未运行优化</div><div class="timing-grid"><div v-for="t in [{id:'read',name:'读数据'},{id:'build',name:'建模'},{id:'solve',name:'求解'},{id:'n1_check',name:'N−1 校核'}]" :key="t.id"><span>{{t.name}}</span><strong>{{fmt(s.results?.result?.timings_s?.[t.id])}}<small v-if="s.results?.result?.timings_s?.[t.id]!=null"> s</small></strong></div></div><details open><summary>运行日志</summary><pre class="log-console">{{liveLogs.length?liveLogs.join('\n'):(s.job?.logs||[]).map((l:any)=>typeof l==='string'?l:l.message||JSON.stringify(l)).join('\n')||'尚无外部运行日志。'}}</pre></details><div class="panel-bottom-actions"><span class="small-note">{{s.results?.result?.messages?.join('；')}}</span><el-button type="primary" :disabled="!s.results?.result" @click="s.step=6" data-testid="go-results">查看结果与网架 <UiIcon name="arrow" :size="15"/></el-button></div></section></div></template>